// ====================================================================
//  PROCESS LIBRARY  -- edit this node to add your own plants.
//  Every key is optional; anything you leave out keeps its current
//  value. Selecting a preset always resets the loop to manual.
//
//    ts     controller scan and integration step, s
//           time compression on the trend is ts/0.2 -- a boiler at
//           ts=5 runs 25x faster than real life, which is the only
//           way a 90 s time constant is practical to tune by hand
//    window trend width, s of process time
//    lead   inverse response, s  (>0 = PV moves the wrong way first)
//    tau2   second-order stage, s;  zeta2 < 1 makes it resonant
//    rate   actuator slew limit, %/s
//    pv0    where PV sits at the starting output (bias is derived)
// ====================================================================
flow.set('plants', {

  bench: {
    icon: 'hx', role: 'Well behaved',
    pv: 'Outlet temperature', mv: 'Steam valve position, %',
    fce: 'Globe control valve, pneumatic positioner',
    fceNote: 'Fast, near-linear, no meaningful stroke limit. Nothing here will surprise you, which is the point.',
    name: 'Bench FOPDT',
    note: 'Generic self-regulating loop -- a heat exchanger or a flow loop. Start here; the mechanics are easiest to see when nothing exotic is happening.',
    ts: 0.2, window: 180,
    model: 'fopdt', K: 1.6, tau: 12, theta: 3, pv0: 48, noise: 0.25,
    lead: 0, tau2: 0, zeta2: 1, rate: 0, opMan: 30, sp: 50
  },

  pv_voltvar: {
    icon: 'sun', role: 'Dead-time dominant',
    pv: 'Voltage at the point of interconnection', mv: 'Fleet reactive power command, % of Qmax',
    fce: 'PV inverters, Q setpoint written over SCADA',
    fceNote: 'The plant controller writes a reactive setpoint and several hundred inverters answer within a few hundred ms. The delay is the controller scan plus the comms round trip out and the metering coming back, not the inverters being slow.',
    name: 'PV plant volt/VAR at the POI',
    note: 'Plant controller trims inverter reactive setpoints to hold voltage at the point of interconnection. The lag is the inverters answering (fast); the dead time is the plant-controller scan plus the comms round trip out to the fleet and back through metering. theta/tau is about 2.5, so this is dead-time dominant and there is very little gain available.',
    ts: 0.2, window: 120,
    model: 'fopdt', K: 1.2, tau: 0.8, theta: 2.0, pv0: 50, noise: 0.35,
    lead: 0, tau2: 0, zeta2: 1, rate: 0, opMan: 50, sp: 50
  },

  pv_weakgrid: {
    icon: 'sunweak', role: 'Gain you do not control',
    pv: 'Voltage at the point of interconnection', mv: 'Fleet reactive power command, % of Qmax',
    fce: 'PV inverters, Q setpoint written over SCADA',
    fceNote: 'Same hardware as the strong-grid case. Only the grid behind it changed, and that is enough to undo your tuning.',
    name: 'PV volt/VAR, weak grid',
    note: 'The same plant on a weak interconnection. dV/dQ is nearly three times higher because process gain in a volt/VAR loop is set by grid strength -- and grid strength changes with line outages and neighbouring generation. A tune that was comfortable on the strong-grid case will hunt here. Tune for the weakest case you expect to see.',
    ts: 0.2, window: 120,
    model: 'fopdt', K: 3.2, tau: 0.8, theta: 2.0, pv0: 50, noise: 0.45,
    lead: 0, tau2: 0, zeta2: 1, rate: 0, opMan: 50, sp: 50
  },

  boiler_drum: {
    icon: 'drum', role: 'Lies to you first',
    pv: 'Drum level, % of span', mv: 'Feedwater flow demand, %',
    fce: 'Feedwater regulating valve',
    fceNote: 'On most units this is really a cascade: this demand goes to a feedwater flow controller, and that one strokes the valve. Single-element control, which is what you have here, is the hard version.',
    name: 'Boiler drum level',
    note: 'Integrating and inverse responding. Open feedwater and the level DROPS first, because cold water collapses steam bubbles below the surface, then it ramps up. Anything that reacts to the first few seconds of trend does exactly the wrong thing. Noisy too -- the surface is boiling. This is why real units run three-element control instead of a single PID.',
    ts: 0.5, window: 600,
    model: 'integrating', Ki: 0.15, theta: 2, lead: 6, pv0: 50, noise: 0.8,
    tau2: 0, zeta2: 1, rate: 0, opMan: 50, sp: 50
  },

  boiler_superheat: {
    icon: 'coil', role: 'Slow and layered',
    pv: 'Final steam temperature', mv: 'Attemperator spray flow, %',
    fce: 'Desuperheater spray water control valve',
    fceNote: 'Spray water evaporates fast, but the tube metal downstream does not. That second thermal mass is the tau2 term, and it is why the half rule matters here.',
    name: 'Boiler superheat steam temperature',
    note: 'Spray attemperator to final steam temperature. Long lag, long dead time, and a second thermal lag in the tube metal. Running at ts=5 s so a test takes a minute instead of half an hour. Real units cascade a fast spray-outlet loop inside this one, which is the honest answer to how slow it is.',
    ts: 5, window: 3000,
    model: 'fopdt', K: 1.1, tau: 90, theta: 25, tau2: 40, zeta2: 1,
    pv0: 55, noise: 0.3, lead: 0, rate: 0, opMan: 25, sp: 55
  },

  wind_pitch: {
    icon: 'wind', role: 'Fights the structure',
    pv: 'Rotor speed, % of rated', mv: 'Collective blade pitch demand',
    fce: 'Electric pitch drives, three blades',
    fceNote: 'The drives cannot slew faster than 6 %/s of pitch range, so above a certain gain the controller is asking for motion it will never get. Signs are normalised: real pitch has negative process gain and a direct-acting controller.',
    name: 'Wind turbine collective pitch',
    note: 'Above rated wind, pitch holds rotor speed. Fast loop, almost no dead time -- but the pitch drives are rate limited to 6 %/s and there is a lightly damped tower fore-aft mode near 0.3 Hz sitting inside the loop. Push the gain and you will not lose the speed loop, you will excite the tower. Signs are normalised here: real pitch has negative process gain and a direct-acting controller.',
    ts: 0.1, window: 120,
    model: 'fopdt', K: 1.4, tau: 2.5, theta: 0.3, tau2: 0.55, zeta2: 0.15,
    rate: 6, lead: 0, pv0: 50, noise: 0.3, opMan: 35, sp: 50
  }

});

// Plant. One scan: slew limit -> dead time -> dynamics -> noise.
// Consumes the OP the controller left last scan; a PLC behaves the same.
var c = flow.get('cfg'), s = flow.get('st');
var Ts = c.ts;

s.simT += Ts * 1000;

// --- actuator slew limit (pitch drives, big valves, tap changers) ---
var tgt = s.op;
if (c.rate > 0) {
  var lim = c.rate * Ts;
  s.opRL += Math.max(-lim, Math.min(lim, tgt - s.opRL));
} else {
  s.opRL = tgt;
}

// --- transport delay -----------------------------------------------
var nD = Math.max(0, Math.round(c.theta / Ts));
s.delay.push(s.opRL);
var u = (s.delay.length > nD) ? s.delay.shift() : s.delay[0];

u = u + c.dist;              // load disturbance enters at the actuator

// --- dominant dynamics ---------------------------------------------
var y;
if (c.model === 'integrating') {
  // k'(1 - lead*s)/s : level ramps, but dips first if lead > 0
  s.lag1 += Ts * c.Ki * (u - 50);
  s.lag1 = Math.min(200, Math.max(-100, s.lag1));
  y = s.lag1 - c.Ki * c.lead * (u - 50);
} else {
  // K(1 - lead*s)/(tau*s + 1), exact ZOH on the lag
  var a = Math.exp(-Ts / Math.max(c.tau, 1e-6));
  s.lag1 = a * s.lag1 + (1 - a) * (c.K * u + c.pvBias);
  if (c.lead !== 0) {
    var xu = c.K * u + c.pvBias;
    y = s.lag1 * (1 + c.lead / c.tau) - xu * (c.lead / c.tau);
  } else {
    y = s.lag1;
  }
}

// --- optional second-order stage ------------------------------------
// zeta2 = 1 is a second thermal lag; zeta2 << 1 is a structural mode
// (tower fore-aft, drive train) sitting inside the loop.
if (c.tau2 > 0) {
  // Exact zero-order-hold discretisation of wn^2/(s^2 + 2*z*wn*s + wn^2).
  // Euler gets the ring frequency wrong by tens of percent at these step
  // sizes, which matters when the whole point is where the mode sits.
  var wn = 1 / c.tau2, z = c.zeta2, sg = z * wn, E = Math.exp(-sg * Ts), co, si;
  if (z < 1) {
    var wd = wn * Math.sqrt(1 - z * z);
    co = Math.cos(wd * Ts); si = Math.sin(wd * Ts) / wd;
  } else if (z > 1) {
    var wh = wn * Math.sqrt(z * z - 1);
    co = Math.cosh(wh * Ts); si = Math.sinh(wh * Ts) / wh;
  } else { co = 1; si = Ts; }
  var f11 = E * (co + sg * si), f12 = E * si;
  var f21 = -E * wn * wn * si,  f22 = E * (co - sg * si);
  var yN = f11 * s.y2 + f12 * s.v2 + (1 - f11) * y;
  s.v2   = f21 * (s.y2 - y) + f22 * s.v2;
  s.y2   = yN;
  y = s.y2;
} else {
  s.y2 = y; s.v2 = 0;
}

s.pvTrue = Math.min(160, Math.max(-60, y));

// --- measurement ----------------------------------------------------
var n = 0;
if (c.noise > 0) {
  var r1 = Math.random() || 1e-9, r2 = Math.random();
  n = c.noise * Math.sqrt(-2 * Math.log(r1)) * Math.cos(2 * Math.PI * r2);
}
s.pv = s.pvTrue + n;

flow.set('st', s);
msg.payload = { pv: s.pv };
return msg;

// ISA (dependent) form PID, written the way a decent PLC block behaves:
// derivative on the measurement, filtered derivative, back-calculation
// anti-windup, bumpless manual-to-auto.
var c = flow.get('cfg'), s = flow.get('st');
var Ts = c.ts, pv = msg.payload.pv, sp = c.sp;

if (c.extPID) {
  // OP is being written by OpenPLC over Modbus. Skip the internal
  // controller but keep trending and scoring the loop.
  s.pvf = pv; s.pvfPrev = pv;
} else {

var sign = (c.action === 'direct') ? -1 : 1;
var e = sign * (sp - pv);

// derivative acts on PV, so a setpoint step produces no derivative kick
var Tf = (c.Td > 0) ? c.Td / Math.max(c.N, 1) : Ts;
s.pvf += (Ts / (Tf + Ts)) * (pv - s.pvf);
var D = 0;
if (c.Td > 0) D = -sign * c.Kc * c.Td * (s.pvf - s.pvfPrev) / Ts;
s.pvfPrev = s.pvf;

var P = c.Kc * e;

// I is the AUTOMATIC reset, bias is the MANUAL one. With no integral action
// there is no automatic reset at all, so fold whatever the integral was
// holding into bias -- bumpless, and it keeps the displayed equation exact.
if (c.Ti <= 0 && s.I !== 0) { c.bias += s.I; s.I = 0; flow.set('cfg', c); }

s.P = P; s.D = D; s.e = e;

if (c.auto && c.Ti > 0) s.I += c.Kc * (Ts / c.Ti) * e;

var op = P + s.I + D + c.bias;
var opSat = Math.min(c.opMax, Math.max(c.opMin, op));

if (!c.auto) {
  // track, so the flip to auto is bumpless -- via the integral if there is
  // one, otherwise via bias, which is exactly what manual reset means
  if (c.Ti > 0) { s.I = c.opMan - P - D - c.bias; }
  else { s.I = 0; c.bias = c.opMan - P - D; flow.set('cfg', c); }
  s.op = Math.min(c.opMax, Math.max(c.opMin, c.opMan));
} else {
  // P-only cannot wind up, so only back-calculate when integral is running
  if (opSat !== op && c.Ti > 0) s.I = opSat - P - D - c.bias;
  s.op = opSat;
}

}   // end internal controller

// --- response scoring, reset by the UI on every SP or load change ---
s.iae += Math.abs(sp - pv) * Ts;
s.tEvent += Ts;
var step = sp - s.pvAtEvent;
if (Math.abs(step) > 1) {
  if (step > 0 ? (pv > s.peak) : (pv < s.peak)) s.peak = pv;
  if (Math.abs(sp - pv) > 0.02 * Math.abs(step)) s.tSettle = s.tEvent;
}

flow.set('st', s);

var h = flow.get('hist');
h.push([s.simT, +sp.toFixed(3), +pv.toFixed(3), +s.op.toFixed(3), +s.opRL.toFixed(3)]);
while (h.length > 6000) h.shift();
flow.set('hist', h);

return null;

var c = flow.get('cfg') || {}, s = flow.get('st') || {}, h = flow.get('hist') || [];
var since = Number((msg.req.query && msg.req.query.since) || 0);

var pts = since ? h.filter(function (p) { return p[0] > since; }) : h;
if (pts.length > 1200) pts = pts.slice(-1200);

var step = c.sp - (s.pvAtEvent || 0);
var os = null;
if (Math.abs(step) > 1) os = 100 * (s.peak - c.sp) / step;

msg.payload = {
  now: s.simT || 0,
  cfg: c,
  pts: pts,
  m: {
    pv: s.pv, op: s.op, opRL: s.opRL, i: s.I, p: s.P, d: s.D, e: s.e,
    iae: s.iae, settle: s.tSettle, tEvent: s.tEvent,
    simT: s.simT, speed: (c.ts || 0.2) / 0.2,
    overshoot: os
  }
};
msg.headers = { 'Cache-Control': 'no-store' };
return msg;

var c = flow.get('cfg'), s = flow.get('st');
var b = msg.payload || {};

// selecting a plant from the library
if (b.preset) {
  var lib = flow.get('plants') || {};
  var pl = lib[b.preset];
  if (pl) {
    Object.keys(pl).forEach(function (k) {
      if (k !== 'name' && k !== 'note') c[k] = pl[k];
    });
    c.preset = b.preset;
    c.auto = false;               // every new plant starts in manual
    c.dist = 0;
    // pv0 is where the plant sits at the starting output; back out the bias
    if (pl.pv0 !== undefined) {
      c.pvBias = (c.model === 'integrating') ? pl.pv0 : pl.pv0 - c.K * c.opMan;
    }
    b.reset = true;
  }
}

if (b.reset) {
  // Start settled at the manual output, with the actuator already there --
  // otherwise the plant sees a step before the controller's first pass.
  var pv0 = (c.model === 'integrating') ? c.pvBias : c.K * c.opMan + c.pvBias;
  s.simT = 0;
  s.pvTrue = s.pv = s.pvf = s.pvfPrev = s.lag1 = s.y2 = pv0;
  s.v2 = 0;
  s.op = s.opRL = c.opMan;
  s.I = (c.Ti > 0) ? (c.opMan - c.bias) : 0;
  s.P = 0; s.D = 0; s.e = 0;
  s.delay = [];
  s.iae = 0; s.tEvent = 0; s.pvAtEvent = pv0; s.peak = pv0; s.tSettle = 0;
  flow.set('hist', []);
}

var numeric = ['ts','window','K','tau','theta','Ki','lead','tau2','zeta2','rate','pvBias','noise','dist',
               'sp','Kc','Ti','Td','bias','N','opMan','opMin','opMax'];
numeric.forEach(function (k) {
  if (b[k] !== undefined && b[k] !== null && b[k] !== '') {
    var v = Number(b[k]);
    if (!isNaN(v)) { if (v !== c[k]) { if (k === 'sp' || k === 'dist') b.event = true; } c[k] = v; }
  }
});
if (b.model !== undefined)  c.model  = b.model;
if (b.action !== undefined) c.action = b.action;
if (b.auto !== undefined)   c.auto   = !!b.auto;
if (b.extPID !== undefined) c.extPID = !!b.extPID;

if (b.event) {
  s.iae = 0; s.tEvent = 0; s.pvAtEvent = s.pv; s.peak = s.pv; s.tSettle = 0;
}

flow.set('cfg', c);
flow.set('st', s);
msg.payload = { ok: true };
return msg;
